import type { SourceOffset } from './sourceOffset.js';
import type { SourceCursorPosition } from './cursorPosition.js';
import { OffsetRange } from './offsetRange.js';

export class Selection {
	static collapsed(offset: SourceOffset, affinity?: SourceCursorPosition['affinity']): Selection {
		return new Selection(offset, offset, affinity);
	}

	declare readonly activeAffinity?: SourceCursorPosition['affinity'];

	constructor(
		readonly anchor: SourceOffset,
		readonly active: SourceOffset,
		activeAffinity?: SourceCursorPosition['affinity'],
	) {
		if (activeAffinity) { this.activeAffinity = activeAffinity; }
	}

	get isCollapsed(): boolean {
		return this.anchor === this.active;
	}

	get isForward(): boolean {
		return this.active >= this.anchor;
	}

	get range(): OffsetRange {
		return this.isForward
			? new OffsetRange(this.anchor, this.active)
			: new OffsetRange(this.active, this.anchor);
	}

	collapseToActive(): Selection {
		return Selection.collapsed(this.active, this.activeAffinity);
	}

	withActive(active: SourceOffset, affinity?: SourceCursorPosition['affinity']): Selection {
		return new Selection(this.anchor, active, affinity);
	}
}
