import { autorun, Disposable, type IReader } from '@vscode/observables';
import { SuggestModel, type SuggestItem, type SuggestNavigation } from './suggestModel.js';

export class SuggestWidget<T extends SuggestItem = SuggestItem> extends Disposable {
	readonly element: HTMLDivElement;
	readonly listElement: HTMLDivElement;
	private readonly _message: HTMLDivElement;
	private readonly _savedAttributes = new Map<string, string | null>();
	private _items: readonly T[] | undefined;
	private _disposed = false;
	private _pendingReveal: number | undefined;

	constructor(private readonly _options: SuggestWidgetOptions<T>) {
		super();
		if (!_options.id || /\s/.test(_options.id)) {
			throw new Error('Suggest widget id must be nonempty and contain no whitespace.');
		}
		const document = _options.focusTarget.ownerDocument;
		this.element = document.createElement('div');
		this.element.className = 'md-suggest-widget';
		this.listElement = document.createElement('div');
		this.listElement.className = 'md-suggest-list';
		this.listElement.id = _options.id;
		this.listElement.setAttribute('role', 'listbox');
		this.listElement.setAttribute('aria-label', _options.label ?? 'Suggestions');
		this._message = document.createElement('div');
		this._message.className = 'md-suggest-message';
		this._message.setAttribute('role', 'status');
		this._message.setAttribute('aria-live', 'polite');
		this.element.append(this.listElement, this._message);

		const onKeyDown = (event: KeyboardEvent): void => { this.handleKeyDown(event); };
		const onPointerDown = (event: PointerEvent): void => {
			if (event.button !== 0) { return; }
			event.preventDefault();
			event.stopPropagation();
			const row = this._rowFromEvent(event);
			if (row?.dataset.suggestId !== undefined) { _options.model.select(row.dataset.suggestId); }
		};
		const onClick = (event: MouseEvent): void => {
			if (event.button !== 0) { return; }
			const row = this._rowFromEvent(event);
			if (row?.dataset.suggestId === undefined) { return; }
			event.preventDefault();
			event.stopPropagation();
			if (_options.model.select(row.dataset.suggestId)) { _options.model.accept('pointer'); }
		};
		if (_options.listenForKeyboard !== false) {
			_options.focusTarget.addEventListener('keydown', onKeyDown, true);
			this._register({ dispose: () => _options.focusTarget.removeEventListener('keydown', onKeyDown, true) });
		}
		this.element.addEventListener('pointerdown', onPointerDown);
		this.element.addEventListener('click', onClick);
		this._register({ dispose: () => {
			this.element.removeEventListener('pointerdown', onPointerDown);
			this.element.removeEventListener('click', onClick);
		} });
		this._register(autorun(reader => this._render(reader)));
		const resizeObserver = new ResizeObserver(() => this._revealSelection());
		resizeObserver.observe(this.listElement);
		this._register({ dispose: () => resizeObserver.disconnect() });
	}

	handleKeyDown(event: KeyboardEvent): boolean {
		if (this._disposed || event.defaultPrevented || event.isComposing
			|| event.altKey || event.ctrlKey || event.metaKey || event.shiftKey
			|| this._options.model.state.get().kind === 'closed') {
			return false;
		}
		const navigation: Partial<Record<string, SuggestNavigation>> = {
			ArrowDown: 'next', ArrowUp: 'previous', PageDown: 'nextPage',
			PageUp: 'previousPage', Home: 'first', End: 'last',
		};
		const model = this._options.model;
		const direction = navigation[event.key];
		// Consume before callbacks so an accepted suggestion cannot also trigger editor input.
		const canHandle = event.key === 'Escape'
			|| (model.state.get().kind === 'ready' && (direction !== undefined || event.key === 'Enter' || event.key === 'Tab'));
		if (!canHandle) { return false; }
		event.preventDefault();
		event.stopImmediatePropagation();
		if (direction) {
			const rowHeight = this.listElement.firstElementChild?.getBoundingClientRect().height ?? 22;
			model.navigate(direction, Math.max(1, Math.floor(this.listElement.clientHeight / (rowHeight || 22))));
		} else if (event.key === 'Escape') { model.cancel(); }
		else { model.accept(event.key === 'Tab' ? 'tab' : 'enter'); }
		return true;
	}

	override dispose(): void {
		if (this._disposed) { return; }
		this._disposed = true;
		if (this._pendingReveal !== undefined) { cancelAnimationFrame(this._pendingReveal); }
		super.dispose();
		this._restoreAttributes();
		this.element.remove();
	}

	private _rowFromEvent(event: MouseEvent): HTMLElement | undefined {
		const target = event.composedPath().find(node => node === this.listElement
			|| (node instanceof this.element.ownerDocument.defaultView!.HTMLElement && node.parentElement === this.listElement));
		return target instanceof this.element.ownerDocument.defaultView!.HTMLElement && target !== this.listElement ? target : undefined;
	}

	private _render(reader: IReader): void {
		const state = this._options.model.state.read(reader);
		const open = state.kind !== 'closed';
		this.element.hidden = !open;
		if (!open) {
			this._items = undefined;
			this.listElement.replaceChildren();
			this._message.textContent = '';
			this._restoreAttributes();
			return;
		}
		if (this._savedAttributes.size === 0) {
			for (const name of ['aria-controls', 'aria-activedescendant', 'aria-autocomplete', 'aria-haspopup', 'aria-expanded']) {
				this._savedAttributes.set(name, this._options.focusTarget.getAttribute(name));
			}
			const controls = this._savedAttributes.get('aria-controls');
			this._options.focusTarget.setAttribute('aria-controls', [controls, this.listElement.id].filter(Boolean).join(' '));
			this._options.focusTarget.setAttribute('aria-autocomplete', 'list');
			this._options.focusTarget.setAttribute('aria-haspopup', 'listbox');
			this._options.focusTarget.setAttribute('aria-expanded', 'true');
		}
		this.listElement.hidden = state.kind !== 'ready';
		this._message.hidden = state.kind === 'ready';
		this.element.dataset.state = state.kind;
		this.listElement.setAttribute('aria-busy', String(state.kind === 'loading'));
		if (state.kind !== 'ready') {
			this._items = undefined;
			this.listElement.replaceChildren();
			this._options.focusTarget.removeAttribute('aria-activedescendant');
			this._message.setAttribute('role', state.kind === 'error' ? 'alert' : 'status');
			this._message.setAttribute('aria-live', state.kind === 'error' ? 'assertive' : 'polite');
			this._message.textContent = state.kind === 'loading' ? 'Loading...'
				: state.kind === 'empty' ? 'No suggestions.' : state.message;
			return;
		}
		this._message.textContent = '';
		if (state.items !== this._items) {
			this._items = state.items;
			this.listElement.replaceChildren(...state.items.map((item, index) => this._createRow(item, index)));
		}
		for (const [index, row] of Array.from(this.listElement.children).entries()) {
			row.setAttribute('aria-selected', String(index === state.selectedIndex));
		}
		const row = this.listElement.children[state.selectedIndex] as HTMLElement;
		this._options.focusTarget.setAttribute('aria-activedescendant', row.id);
		this._revealSelection();
		if (!this.element.isConnected && this._pendingReveal === undefined) {
			this._pendingReveal = requestAnimationFrame(() => {
				this._pendingReveal = undefined;
				this._revealSelection();
			});
		}
	}

	private _revealSelection(): void {
		const state = this._options.model.state.get();
		if (state.kind !== 'ready' || !this.element.isConnected) { return; }
		const row = this.listElement.children[state.selectedIndex] as HTMLElement | undefined;
		if (!row) { return; }
		// Only scroll the list; scrollIntoView can also move the editor and its page.
		const top = row.offsetTop;
		const bottom = top + row.offsetHeight;
		if (top < this.listElement.scrollTop) { this.listElement.scrollTop = top; }
		else if (bottom > this.listElement.scrollTop + this.listElement.clientHeight) {
			this.listElement.scrollTop = bottom - this.listElement.clientHeight;
		}
	}

	private _createRow(item: T, index: number): HTMLDivElement {
		const document = this.element.ownerDocument;
		const row = document.createElement('div');
		row.className = 'md-suggest-row';
		row.id = `${this.listElement.id}-option-${index}`;
		row.dataset.suggestId = item.id;
		row.setAttribute('role', 'option');
		row.setAttribute('aria-label', [item.label, item.type].filter(Boolean).join(', '));
		row.title = [item.label, item.detail, item.type].filter(Boolean).join(' - ');
		const icon = document.createElement('span');
		icon.className = `md-suggest-icon codicon codicon-${completionIcons[item.type ?? 'Text'] ?? 'symbol-property'}`;
		icon.setAttribute('aria-hidden', 'true');
		row.appendChild(icon);
		const label = document.createElement('span');
		label.className = 'md-suggest-label';
		const length = Math.max(0, Math.min(item.highlightLength ?? 0, item.label.length));
		const match = document.createElement('span');
		match.className = 'md-suggest-match';
		match.textContent = item.label.slice(0, length);
		label.append(match, document.createTextNode(item.label.slice(length)));
		row.appendChild(label);
		if (item.detail) {
			const detail = document.createElement('span');
			detail.className = 'md-suggest-detail';
			detail.textContent = item.detail;
			row.appendChild(detail);
		}
		return row;
	}

	private _restoreAttributes(): void {
		for (const [name, value] of this._savedAttributes) {
			if (value === null) { this._options.focusTarget.removeAttribute(name); }
			else { this._options.focusTarget.setAttribute(name, value); }
		}
		this._savedAttributes.clear();
	}
}

export interface SuggestWidgetOptions<T extends SuggestItem> {
	readonly model: SuggestModel<T>;
	readonly focusTarget: HTMLElement;
	readonly id: string;
	readonly label?: string;
	readonly listenForKeyboard?: boolean;
}

const completionIcons: Readonly<Record<string, string>> = {
	Text: 'symbol-text', Method: 'symbol-method', Function: 'symbol-method', Constructor: 'symbol-method',
	Field: 'symbol-field', Variable: 'symbol-variable', Class: 'symbol-class', Interface: 'symbol-interface',
	Module: 'symbol-namespace', Property: 'symbol-property', Unit: 'symbol-ruler', Value: 'symbol-enum',
	Enum: 'symbol-enum', Keyword: 'symbol-keyword', Snippet: 'symbol-snippet', Color: 'symbol-color',
	File: 'symbol-file', Reference: 'symbol-reference', Folder: 'symbol-folder', EnumMember: 'symbol-enum-member',
	Constant: 'symbol-constant', Struct: 'symbol-struct', Event: 'symbol-event', Operator: 'symbol-operator',
	TypeParameter: 'symbol-type-parameter',
};
