import { Disposable, autorun } from '@vscode/observables';
import type { RenameModel, RenameSession } from './renameModel.js';

export class RenameWidget<TContext = undefined> extends Disposable {
	readonly element: HTMLDivElement;
	readonly inputElement: HTMLInputElement;
	private readonly _message: HTMLDivElement;
	private _anchor: RenameAnchor | undefined;
	private _focusedSession: RenameSession<TContext> | undefined;

	constructor(
		private readonly _container: HTMLElement,
		private readonly _model: RenameModel<TContext>,
		private readonly _options: RenameWidgetOptions = {},
	) {
		super();
		const doc = _container.ownerDocument;
		this.element = doc.createElement('div');
		this.element.className = 'md-rename-widget';
		this.element.setAttribute('role', 'dialog');
		this.element.setAttribute('aria-label', 'Rename');

		const shell = doc.createElement('div');
		shell.className = 'md-rename-input-shell';
		this.inputElement = doc.createElement('input');
		this.inputElement.className = 'md-rename-input';
		this.inputElement.type = 'text';
		this.inputElement.setAttribute('aria-label', 'New name');
		this.inputElement.autocomplete = 'off';
		this.inputElement.spellcheck = false;
		shell.appendChild(this.inputElement);
		this._message = doc.createElement('div');
		this._message.className = 'md-rename-message';
		this._message.id = `md-rename-message-${crypto.randomUUID()}`;
		this._message.setAttribute('role', 'status');
		this._message.setAttribute('aria-live', 'polite');
		this._message.setAttribute('aria-atomic', 'true');
		this.inputElement.setAttribute('aria-describedby', this._message.id);
		this.element.append(shell, this._message);
		_container.appendChild(this.element);
		this._register({ dispose: () => this.element.remove() });

		const onInput = (): void => this._model.name.set(this.inputElement.value, undefined);
		const onKeyDown = (event: KeyboardEvent): void => {
			event.stopPropagation();
			if (event.isComposing) { return; }
			if (event.key === 'Escape') {
				event.preventDefault();
				this._model.cancel();
			} else if (event.key === 'Enter' && !event.altKey && !event.ctrlKey && !event.metaKey && !event.shiftKey) {
				event.preventDefault();
				void this._model.submit();
			}
		};
		const onPointerDown = (event: PointerEvent): void => event.stopPropagation();
		this.inputElement.addEventListener('input', onInput);
		this.element.addEventListener('keydown', onKeyDown);
		this.element.addEventListener('pointerdown', onPointerDown);
		this._register({ dispose: () => {
			this.inputElement.removeEventListener('input', onInput);
			this.element.removeEventListener('keydown', onKeyDown);
			this.element.removeEventListener('pointerdown', onPointerDown);
		} });

		this._register(autorun(reader => {
			const session = _model.session.read(reader);
			const name = _model.name.read(reader);
			const pending = _model.pending.read(reader);
			const message = _model.error.read(reader)?.message || _model.validationMessage.read(reader);
			const wasFocused = this.element.contains(doc.activeElement);
			this.element.hidden = !session;
			if (this.inputElement.value !== name) { this.inputElement.value = name; }
			this.inputElement.readOnly = pending;
			this.inputElement.setAttribute('aria-invalid', String(!!message));
			this.element.setAttribute('aria-busy', String(pending));
			this.element.classList.toggle('md-rename-invalid', !!message);
			this._message.textContent = pending ? 'Renaming...' : message || 'Enter to Rename, Escape to Cancel';
			this.inputElement.title = message || 'New name';
			this.layout(this._anchor);
			if (session && session !== this._focusedSession) {
				this._focusedSession = session;
				if (_options.autoFocus !== false) { this.focusAndSelect(); }
			} else if (!session) {
				this._focusedSession = undefined;
				if (wasFocused) { this._options.onDidHide?.(); }
			}
		}));
		const ResizeObserver = doc.defaultView?.ResizeObserver;
		if (ResizeObserver) {
			const observer = new ResizeObserver(() => this.layout(this._anchor));
			observer.observe(_container);
			observer.observe(this.element);
			this._register({ dispose: () => observer.disconnect() });
		}
	}

	focusAndSelect(): void {
		this.inputElement.focus({ preventScroll: true });
		this.inputElement.select();
	}

	/** Anchor coordinates are relative to the positioned container's padding box. */
	layout(anchor?: RenameAnchor): void {
		this._anchor = anchor;
		this.element.classList.toggle('md-rename-overlay', !!anchor);
		if (!anchor) {
			this.element.style.removeProperty('left');
			this.element.style.removeProperty('top');
			return;
		}
		const width = this._container.clientWidth;
		const height = this._container.clientHeight;
		const widgetHeight = this.element.offsetHeight;
		const below = anchor.top + anchor.height;
		const top = below + widgetHeight <= height ? below : anchor.top - widgetHeight;
		this.element.style.left = `${Math.max(0, Math.min(anchor.left, width - this.element.offsetWidth))}px`;
		this.element.style.top = `${Math.max(0, Math.min(top, height - widgetHeight))}px`;
	}
}

export interface RenameWidgetOptions {
	readonly autoFocus?: boolean;
	/** Called when a focused widget closes; the host can restore editor focus. */
	readonly onDidHide?: () => void;
}

export interface RenameAnchor {
	readonly left: number;
	readonly top: number;
	readonly height: number;
}
