import { Disposable } from '@vscode/observables';
import type { CodeBlockAstNode } from '../../parser/ast.js';
import type { BlockViewOptions } from './blockView.js';
import { getCodeBlockText } from './codeBlockText.js';

/** Non-source chrome, kept outside the code's scrolling and source-mapped DOM. */
export class CodeBlockCopyAction extends Disposable {
	readonly element = document.createElement('div');
	private readonly _button = document.createElement('button');
	private readonly _icon = document.createElement('span');
	private readonly _status = document.createElement('span');
	private _copying = false;
	private _closed = false;
	private _resetTimer: ReturnType<typeof setTimeout> | undefined;

	constructor(private _block: CodeBlockAstNode, private _options: BlockViewOptions | undefined) {
		super();
		this.element.className = 'md-code-block-actions';
		this._button.type = 'button';
		this._button.className = 'md-code-block-copy';
		this._button.title = 'Copy code block';
		this._button.setAttribute('aria-label', 'Copy code block');
		this._icon.className = 'codicon codicon-copy';
		this._icon.setAttribute('aria-hidden', 'true');
		this._button.appendChild(this._icon);
		this._status.className = 'md-code-block-copy-status';
		this._status.setAttribute('role', 'status');
		this._status.setAttribute('aria-live', 'polite');
		this.element.append(this._status, this._button);

		const onPointerDown = (event: PointerEvent): void => {
			event.preventDefault();
			event.stopPropagation();
		};
		const onKeyDown = (event: KeyboardEvent): void => {
			// Native Enter/Space activation and Tab navigation, not editor commands.
			event.stopPropagation();
		};
		const onClick = (event: MouseEvent): void => {
			event.stopPropagation();
			void this._copy();
		};
		this._button.addEventListener('pointerdown', onPointerDown);
		this._button.addEventListener('keydown', onKeyDown);
		this._button.addEventListener('click', onClick);
		const suspension = _options?.suspendEditContextWhileFocused?.(this._button);
		this._register({
			dispose: () => {
				this._closed = true;
				clearTimeout(this._resetTimer);
				suspension?.dispose();
				this._button.removeEventListener('pointerdown', onPointerDown);
				this._button.removeEventListener('keydown', onKeyDown);
				this._button.removeEventListener('click', onClick);
			},
		});
	}

	update(block: CodeBlockAstNode, options: BlockViewOptions | undefined): void {
		this._block = block;
		this._options = options;
	}

	private _resetFeedback(): void {
		clearTimeout(this._resetTimer);
		this.element.classList.remove('md-code-block-copy-feedback');
		this._icon.className = 'codicon codicon-copy';
		this._status.textContent = '';
	}

	private async _copy(): Promise<void> {
		if (this._copying || this._closed) { return; }
		this._copying = true;
		this._resetFeedback();
		this._button.setAttribute('aria-busy', 'true');
		try {
			// Pointer-down preserves selection but also suppresses the webview's native focus.
			if (!this._button.ownerDocument.hasFocus()) {
				(this._button.closest<HTMLElement>('.md-editor[tabindex]') ?? this._button).focus({ preventScroll: true });
			}
			const text = getCodeBlockText(this._block);
			if (this._options?.writeClipboardText) {
				await this._options.writeClipboardText(text);
			} else {
				await this._button.ownerDocument.defaultView!.navigator.clipboard.writeText(text);
			}
			if (this._closed) { return; }
			this._icon.className = 'codicon codicon-check';
			this._status.textContent = 'Code block copied';
		} catch (error) {
			if (this._closed) { return; }
			console.error('Failed to copy code block.', error);
			this._icon.className = 'codicon codicon-error';
			this._status.textContent = 'Could not copy code block. Try again.';
		} finally {
			this._copying = false;
			if (!this._closed) {
				this._button.removeAttribute('aria-busy');
				this.element.classList.add('md-code-block-copy-feedback');
				this._resetTimer = setTimeout(() => this._resetFeedback(), 3000);
			}
		}
	}
}
