import type { IDisposable } from '@vscode/observables';

/**
 * The editor operations a clipboard strategy drives. The strategy never
 * touches the model or the DOM directly — it asks through this seam, so the
 * same strategy works regardless of how the editor is wired up.
 */
export interface IClipboardContext {
    /** The element that owns focus and receives clipboard/keyboard events. */
    readonly element: HTMLElement;
    /** The selected source text, or `undefined` when the selection is empty. */
    getSelectedText(): string | undefined;
    /** Delete the current selection (the cut half of cut). */
    deleteSelection(): void;
    /**
     * Run a copy shortcut and return the source text it transfers, or
     * `undefined` when there is nothing to copy: the selection or, when it is
     * empty while the document is editable, the whole caret line including
     * its line break (like the code editor's `emptySelectionClipboard`).
     */
    copy(): string | undefined;
    /** Like {@link copy}, but also deletes the returned source text. */
    cut(): string | undefined;
    /** Paste text, linking a suitable selection when the payload is a URL unless plain text was requested. */
    insertText(text: string, plainText?: boolean): void;
}

export interface NativeClipboardData {
    readonly text: string;
    readonly files: readonly File[];
}

/**
 * Read native clipboard formats through an editable target. Electron can expose
 * file clipboard entries here that navigator.clipboard.read() omits. EditContext
 * roots themselves do not receive execCommand('paste') events.
 * Returns undefined when the host does not support native programmatic paste.
 */
export function readNativeClipboard(
    focusTarget: HTMLElement,
    executePaste: () => void = () => { focusTarget.ownerDocument.execCommand('paste'); },
): NativeClipboardData | undefined {
    const document = focusTarget.ownerDocument;
    const target = createNativeClipboardTarget(document);
    let result: NativeClipboardData | undefined;
    target.addEventListener('paste', event => {
        event.preventDefault();
        event.stopPropagation();
        if (event.clipboardData) {
            result = { text: event.clipboardData.getData('text/plain'), files: [...event.clipboardData.files] };
        }
    });
    focusTarget.append(target);
    target.focus({ preventScroll: true });
    try {
        executePaste();
        return result;
    } finally {
        target.remove();
        focusTarget.focus({ preventScroll: true });
    }
}

function createNativeClipboardTarget(document: Document): HTMLTextAreaElement {
    const target = document.createElement('textarea');
    target.tabIndex = -1;
    target.setAttribute('aria-label', 'Clipboard');
    target.style.cssText = 'position:fixed;left:0;top:0;width:1px;height:1px;opacity:0;pointer-events:none;';
    return target;
}

/**
 * How copy/cut/paste intent reaches the editor. Host environments deliver it
 * differently, so the controller owns no clipboard logic itself — it
 * {@link connect}s a strategy and lets it install whatever listeners it needs.
 *
 * Two implementations ship:
 * - {@link NativeClipboardStrategy} (default) reads the browser's native
 *   `copy`/`cut`/`paste` events and their synchronous `clipboardData`.
 * - {@link AsyncClipboardStrategy} drives the async `navigator.clipboard` API
 *   from Ctrl/Cmd+C/X/V keystrokes, for hosts (e.g. VS Code webviews) that
 *   swallow the native clipboard events before they reach the editor.
 */
export interface IClipboardStrategy {
    /** Copy an explicit payload without changing the editor selection. Falls back to the browser API when omitted. */
    writeText?(text: string): Promise<void>;
    /**
     * Wire up clipboard handling against `context`. The returned disposable
     * tears down every listener the strategy installed.
     */
    connect(context: IClipboardContext): IDisposable;
}

/**
 * Default strategy: handle the browser's native `copy`/`cut`/`paste` events,
 * reading and writing the synchronous {@link ClipboardEvent.clipboardData}.
 * This is the standard rich-editor approach and works wherever the browser
 * actually dispatches those events to the focused element (e.g. a standalone
 * web page).
 */
export class NativeClipboardStrategy implements IClipboardStrategy {
    connect(context: IClipboardContext): IDisposable {
        const onCopy = (e: ClipboardEvent): void => {
            if (findNestedEditableClipboardTarget(e.target, context.element) || isNestedMediaClipboardTarget(e.target, context.element)) { return; }
            const text = context.copy();
            if (text === undefined) { return; }
            e.preventDefault();
            e.clipboardData?.setData('text/plain', text);
        };
        const onCut = (e: ClipboardEvent): void => {
            if (findNestedEditableClipboardTarget(e.target, context.element) || isNestedMediaClipboardTarget(e.target, context.element)) { return; }
            const text = context.cut();
            if (text === undefined) { return; }
            e.preventDefault();
            e.clipboardData?.setData('text/plain', text);
        };
        const onPaste = (e: ClipboardEvent): void => {
            if (findNestedEditableClipboardTarget(e.target, context.element) || isNestedMediaClipboardTarget(e.target, context.element)) { return; }
            e.preventDefault();
            const text = e.clipboardData?.getData('text/plain');
            if (!text) { return; }
            context.insertText(text);
        };

        const el = context.element;
        el.addEventListener('copy', onCopy);
        el.addEventListener('cut', onCut);
        el.addEventListener('paste', onPaste);
        return {
            dispose: () => {
                el.removeEventListener('copy', onCopy);
                el.removeEventListener('cut', onCut);
                el.removeEventListener('paste', onPaste);
            },
        };
    }
}

/**
 * Strategy for hosts that intercept native clipboard shortcuts, notably
 * VS Code webviews. Their preload prevents the default Ctrl/Cmd+C/X/V handling
 * and forwards the keydowns to the host. This strategy handles the keystrokes
 * directly using the async {@link Clipboard} API (`navigator.clipboard`),
 * which webviews are granted.
 *
 * Cut deletes synchronously once the text is captured; the clipboard write is
 * fire-and-forget. Paste must wait for the async read before inserting.
 * Handled keydowns must not reach the host, which may replay native clipboard
 * commands even when the browser's default has been prevented.
 *
 * Hosts can supply a paste callback to read images or other clipboard formats.
 * It receives the original context, whether Shift requested plain text, and
 * native clipboard data when a paste event supplied it. Context menus focus a
 * temporary editable target so native paste works with EditContext roots too.
 * The callback owns asynchronous errors and stale-selection checks. It does
 * not override copy/cut or clipboard handling in nested native inputs.
 */
export class AsyncClipboardStrategy implements IClipboardStrategy {
    constructor(
        private readonly _clipboard: Clipboard = navigator.clipboard,
        private readonly _paste?: (context: IClipboardContext, plainText: boolean, nativeData?: NativeClipboardData) => Promise<void>,
    ) { }

    writeText(text: string): Promise<void> {
        return this._clipboard.writeText(text);
    }

    connect(context: IClipboardContext): IDisposable {
        let nativeTarget: HTMLTextAreaElement | undefined;
        const document = context.element.ownerDocument;
        const window = document.defaultView;
        let hostMenuVisible = document.body.classList.contains('vscode-context-menu-visible');
        const clearNativeTarget = (restoreFocus = false): void => {
            const target = nativeTarget;
            nativeTarget = undefined;
            target?.remove();
            if (restoreFocus) { context.element.focus({ preventScroll: true }); }
        };
        const restoreNativeTarget = (): void => {
            if (nativeTarget && document.activeElement === document.body) {
                nativeTarget.focus({ preventScroll: true });
            }
        };
        const hostMenuObserver = new MutationObserver(() => {
            const visible = document.body.classList.contains('vscode-context-menu-visible');
            if (hostMenuVisible && !visible) { restoreNativeTarget(); }
            hostMenuVisible = visible;
        });
        hostMenuObserver.observe(document.body, { attributes: true, attributeFilter: ['class'] });
        window?.addEventListener('focus', restoreNativeTarget);
        const onPaste = (event: ClipboardEvent): void => {
            if (!event.clipboardData
                || (event.target !== nativeTarget && (findNestedEditableClipboardTarget(event.target, context.element)
                    || isNestedMediaClipboardTarget(event.target, context.element)))) { return; }
            event.preventDefault();
            event.stopPropagation();
            const data = { text: event.clipboardData.getData('text/plain'), files: [...event.clipboardData.files] };
            if (nativeTarget) { clearNativeTarget(true); }
            if (this._paste) {
                void this._paste(context, false, data);
            } else if (data.text) {
                context.insertText(data.text);
            }
        };
        const onContextMenu = (event: MouseEvent): void => {
            if (findNestedEditableClipboardTarget(event.target, context.element)
                || isNestedMediaClipboardTarget(event.target, context.element)) { return; }
            clearNativeTarget();
            const target = nativeTarget = createNativeClipboardTarget(context.element.ownerDocument);
            target.value = context.getSelectedText() ?? '';
            const copyOrCut = (event: ClipboardEvent): void => {
                const text = context.getSelectedText();
                if (text === undefined || !event.clipboardData) { return; }
                event.preventDefault();
                event.stopPropagation();
                event.clipboardData.setData('text/plain', text);
                clearNativeTarget(true);
                if (event.type === 'cut') { context.deleteSelection(); }
            };
            target.addEventListener('copy', copyOrCut);
            target.addEventListener('cut', copyOrCut);
            target.addEventListener('blur', event => {
                // A host context menu blurs the webview without focusing another editor.
                if (event.relatedTarget) { clearNativeTarget(); }
            });
            target.addEventListener('keydown', () => clearNativeTarget(true));
            context.element.append(target);
            target.focus({ preventScroll: true });
            target.select();
        };
        const onKeyDown = (e: KeyboardEvent): void => {
            const ctrl = e.ctrlKey || e.metaKey;
            if (!ctrl || e.altKey) { return; }
            const nestedEditable = findNestedEditableClipboardTarget(e.target, context.element);
            if (nestedEditable) {
                handleNestedEditableClipboard(e, nestedEditable, this._clipboard);
                return;
            }
            if (isNestedMediaClipboardTarget(e.target, context.element)) { return; }

            switch (e.key.toLowerCase()) {
                case 'c': {
                    const text = context.copy();
                    if (text === undefined) { return; }
                    e.preventDefault();
                    e.stopPropagation();
                    void this._clipboard.writeText(text);
                    break;
                }
                case 'x': {
                    const text = context.cut();
                    if (text === undefined) { return; }
                    e.preventDefault();
                    e.stopPropagation();
                    void this._clipboard.writeText(text);
                    break;
                }
                case 'v': {
                    e.preventDefault();
                    e.stopPropagation();
                    if (this._paste) {
                        void this._paste(context, e.shiftKey);
                        break;
                    }
                    void this._clipboard.readText().then(text => {
                        if (text) { context.insertText(text, e.shiftKey); }
                    });
                    break;
                }
            }
        };

        const el = context.element;
        el.addEventListener('keydown', onKeyDown);
        el.addEventListener('paste', onPaste);
        el.addEventListener('contextmenu', onContextMenu);
        return {
            dispose: () => {
                clearNativeTarget();
                hostMenuObserver.disconnect();
                window?.removeEventListener('focus', restoreNativeTarget);
                el.removeEventListener('keydown', onKeyDown);
                el.removeEventListener('paste', onPaste);
                el.removeEventListener('contextmenu', onContextMenu);
            },
        };
    }
}

/** Finds the nested editable that owns clipboard intent bubbling through the editor root. */
function findNestedEditableClipboardTarget(target: EventTarget | null, editorRoot: HTMLElement): HTMLElement | undefined {
    if (!(target instanceof Node) || target === editorRoot) { return undefined; }
    const element = target instanceof Element ? target : target.parentElement;
    const editable = element?.closest('input, textarea, [contenteditable]:not([contenteditable="false"]), [role="textbox"]');
    return editable instanceof HTMLElement && editorRoot.contains(editable) ? editable : undefined;
}

function isNestedMediaClipboardTarget(target: EventTarget | null, editorRoot: HTMLElement): boolean {
    if (!(target instanceof Node) || target === editorRoot) { return false; }
    const element = target instanceof Element ? target : target.parentElement;
    const media = element?.closest('video, audio');
    return media instanceof HTMLMediaElement && editorRoot.contains(media);
}

function handleNestedEditableClipboard(event: KeyboardEvent, editable: HTMLElement, clipboard: Clipboard): void {
    switch (event.key.toLowerCase()) {
        case 'c': {
            const text = selectedEditableText(editable);
            if (text === undefined) { return; }
            event.preventDefault();
            event.stopPropagation();
            void clipboard.writeText(text);
            return;
        }
        case 'x': {
            const text = selectedEditableText(editable);
            if (text === undefined) { return; }
            event.preventDefault();
            event.stopPropagation();
            void clipboard.writeText(text);
            replaceEditableSelection(editable, '');
            return;
        }
        case 'v':
            event.preventDefault();
            event.stopPropagation();
            void clipboard.readText().then(text => {
                if (text.length > 0) {
                    replaceEditableSelection(editable, text);
                }
            });
    }
}

function selectedEditableText(editable: HTMLElement): string | undefined {
    if (editable instanceof HTMLInputElement || editable instanceof HTMLTextAreaElement) {
        const start = editable.selectionStart;
        const end = editable.selectionEnd;
        if (start === null || end === null || start === end) { return undefined; }
        return editable.value.slice(start, end);
    }
    const selection = editable.ownerDocument.getSelection();
    if (
        !selection
        || selection.isCollapsed
        || selection.rangeCount === 0
        || !editable.contains(selection.getRangeAt(0).commonAncestorContainer)
    ) {
        return undefined;
    }
    return selection.toString();
}

function replaceEditableSelection(editable: HTMLElement, text: string): void {
    if (editable instanceof HTMLInputElement || editable instanceof HTMLTextAreaElement) {
        const start = editable.selectionStart ?? editable.value.length;
        const end = editable.selectionEnd ?? start;
        editable.setRangeText(text, start, end, 'end');
        editable.dispatchEvent(new InputEvent('input', {
            bubbles: true,
            inputType: text.length === 0 ? 'deleteByCut' : 'insertFromPaste',
            data: text,
        }));
        return;
    }

    const selection = editable.ownerDocument.getSelection();
    if (!selection || selection.rangeCount === 0 || !editable.contains(selection.getRangeAt(0).commonAncestorContainer)) {
        return;
    }
    const range = selection.getRangeAt(0);
    range.deleteContents();
    const node = editable.ownerDocument.createTextNode(text);
    range.insertNode(node);
    range.setStartAfter(node);
    range.collapse(true);
    selection.removeAllRanges();
    selection.addRange(range);
    editable.dispatchEvent(new InputEvent('input', {
        bubbles: true,
        inputType: text.length === 0 ? 'deleteByCut' : 'insertFromPaste',
        data: text,
    }));
}
