import { OffsetRange } from '../core/offsetRange.js';
import { Selection } from '../core/selection.js';
import { StringEdit, StringReplacement } from '../core/stringEdit.js';
import { lineBreakLengthAt, lineStart, previousLineBreakStart } from '../core/lines.js';
import type { TableColumnAlignment } from '../parser/ast.js';
import { parse } from '../parser/parse.js';
import {
	tableCellAt, tableLayoutAt, tableLayouts,
	type TableCellPosition, type TableLayout, type TableRowLayout,
} from '../model/tableLayout.js';
import type { CursorCommandContext, EditCommand } from './types.js';

/**
 * Cell-scoped table editing.
 *
 * A table's pipes, padding, row line breaks, and delimiter row are structure:
 * typing, pasting, and deleting only ever touch cell content, and structural
 * changes (rows, columns, alignment) are explicit commands that rewrite the
 * Markdown so the table always stays a valid GFM table.
 */

export interface EditResult {
	readonly edit: StringEdit;
	readonly selection: Selection;
}

/** `undefined` when the edit does not involve a table; otherwise the (possibly empty) table-safe result. */
export type TableEditOutcome = { readonly result: EditResult | undefined } | undefined;

export type TableRowPlacement = 'above' | 'below';
export type TableColumnPlacement = 'left' | 'right';

/**
 * The parts of `range` that may be deleted. Inside a table only cell content
 * is deletable, unless `range` covers the whole table. Returns `undefined`
 * when `range` does not touch table structure.
 */
export function tableSafeDeleteRanges(ctx: CursorCommandContext, range: OffsetRange): readonly OffsetRange[] | undefined {
	let pieces: OffsetRange[] = [range];
	let touched = false;
	for (const table of tableLayouts(ctx.document)) {
		if (table.range.start >= range.endExclusive) { break; }
		if (!table.range.intersects(range) || range.containsRange(table.range)) { continue; }
		const content = table.rows.flatMap(row => row.cells.map(cell => cell.content));
		const next: OffsetRange[] = [];
		for (const piece of pieces) {
			const inside = piece.intersect(table.range);
			if (!inside || inside.isEmpty) { next.push(piece); continue; }
			if (piece.start < inside.start) { next.push(new OffsetRange(piece.start, inside.start)); }
			for (const cell of content) {
				const part = cell.intersect(inside);
				if (part && !part.isEmpty) { next.push(part); }
			}
			if (inside.endExclusive < piece.endExclusive) { next.push(new OffsetRange(inside.endExclusive, piece.endExclusive)); }
		}
		if (next.length !== pieces.length || next.some((p, i) => !p.equals(pieces[i]))) { touched = true; }
		pieces = next;
	}
	return touched ? pieces : undefined;
}

/**
 * Replace `range` with `text` without breaking any table it touches. Text
 * typed into a cell has its pipes escaped and its line breaks turned into
 * `<br>`, so it stays in the cell.
 */
export function tableReplace(ctx: CursorCommandContext, range: OffsetRange, text: string): TableEditOutcome {
	const cell = tableCellAt(ctx.document, range.start);
	const deletions = tableSafeDeleteRanges(ctx, range);
	if (!cell && !deletions) { return undefined; }
	const inserted = cell ? escapeCellText(text, ctx.text.slice(cell.cell.content.start, range.start)) : text;
	const pieces = deletions ?? [range];
	const replacements: StringReplacement[] = [];
	let placed = false;
	for (const piece of pieces) {
		if (!placed && piece.start === range.start) {
			replacements.push(StringReplacement.replace(piece, inserted));
			placed = true;
		} else if (!piece.isEmpty) {
			replacements.push(StringReplacement.delete(piece));
		}
	}
	if (!placed && inserted.length > 0) { replacements.unshift(StringReplacement.insert(range.start, inserted)); }
	const edit = new StringEdit(replacements.filter(r => !r.isEmpty));
	if (edit.isEmpty) { return { result: undefined }; }
	return { result: { edit, selection: Selection.collapsed(range.start + inserted.length) } };
}

/**
 * Make `text` safe as cell content: unescaped `|` become `\|` and line breaks
 * become `<br>`. `before` is the cell text preceding the insertion, so a pipe
 * after an odd run of backslashes is recognized as already escaped.
 */
export function escapeCellText(text: string, before: string): string {
	const singleLine = text.replace(/(?:\r\n|\r|\n)$/, '').replace(/\r\n|\r|\n/g, '<br>');
	let backslashes = /\\*$/.exec(before)![0].length;
	let out = '';
	for (const ch of singleLine) {
		if (ch === '|' && backslashes % 2 === 0) { out += '\\'; }
		out += ch;
		backslashes = ch === '\\' ? backslashes + 1 : 0;
	}
	return out;
}

/** Shift+Enter in a cell: a `<br>` line break that keeps the row intact. */
export const tableLineBreak: EditCommand = ctx => {
	if (!tableCellAt(ctx.document, ctx.selection.range.start)) { return undefined; }
	return tableReplace(ctx, ctx.selection.range, '<br>')?.result;
};

/**
 * Enter in a cell inserts an empty row below the current one (the first body
 * row when on the header) and moves to the same column. Enter in an empty last
 * row removes it and asks the caller to leave the table.
 */
export function tableEnter(ctx: CursorCommandContext): (EditResult & { readonly exitTable?: boolean }) | 'notInTable' {
	const position = tableCellAt(ctx.document, ctx.selection.active);
	if (!position || !tableCellAt(ctx.document, ctx.selection.anchor)) { return 'notInTable'; }
	const { table, row } = position;
	const rowLayout = table.rows[row];
	if (row > 0 && row === table.rows.length - 1 && ctx.selection.isCollapsed
		&& rowLayout.cells.every(cell => cell.content.isEmpty)) {
		const breakLength = lineBreakLengthAt(ctx.text, rowLayout.range.endExclusive);
		const prefixStart = lineStart(ctx.text, rowLayout.range.start);
		const deleteRange = breakLength > 0
			? new OffsetRange(prefixStart, rowLayout.range.endExclusive + breakLength)
			: new OffsetRange(previousLineBreakStart(ctx.text, prefixStart) ?? prefixStart, rowLayout.range.endExclusive);
		const edit = StringEdit.delete(deleteRange);
		const previousRow = table.rows[row - 1];
		return {
			edit,
			selection: Selection.collapsed(previousRow.cells[Math.min(position.column, previousRow.cells.length - 1)].content.endExclusive),
			exitTable: true,
		};
	}
	return insertTableRow(ctx, 'below', position) ?? 'notInTable';
}

/**
 * Tab / Shift+Tab: move to the next / previous cell and select its content.
 * Tab in the last cell appends a row.
 */
export function tableTab(ctx: CursorCommandContext, direction: 'next' | 'previous'): { readonly edit?: StringEdit; readonly selection: Selection } | undefined {
	const position = tableCellAt(ctx.document, ctx.selection.active);
	if (!position) { return undefined; }
	const cells = position.table.rows.flatMap(row => row.cells);
	const index = cells.indexOf(position.cell);
	const target = cells[direction === 'next' ? index + 1 : index - 1];
	if (target) {
		return { selection: new Selection(target.content.start, target.content.endExclusive) };
	}
	if (direction === 'previous') { return { selection: ctx.selection }; }
	const last = position.table.rows.length - 1;
	const appended = insertTableRow(ctx, 'below', { ...position, row: last, column: 0, cell: position.table.rows[last].cells[0] });
	return appended ? { edit: appended.edit, selection: appended.selection } : { selection: ctx.selection };
}

/** Insert an empty row above or below the caret's row. Rows cannot be inserted above the header. */
export function insertTableRow(ctx: CursorCommandContext, placement: TableRowPlacement, at = tableCellAt(ctx.document, ctx.selection.active)): EditResult | undefined {
	if (!at) { return undefined; }
	const { table, row, column } = at;
	if (placement === 'above' && row === 0) { return undefined; }
	const reference = table.rows[row];
	const rowText = _emptyRowText(ctx, table, reference);
	const prefix = ctx.text.slice(lineStart(ctx.text, reference.range.start), reference.range.start);
	let edit: StringEdit;
	let rowStart: number;
	if (placement === 'below') {
		const after = row === 0 && table.delimiterRow ? table.delimiterRow.range.endExclusive : reference.range.endExclusive;
		edit = StringEdit.insert(after, ctx.lineBreak + prefix + rowText);
		rowStart = after + ctx.lineBreak.length + prefix.length;
	} else {
		edit = StringEdit.insert(reference.range.start, rowText + ctx.lineBreak + prefix);
		rowStart = reference.range.start;
	}
	return { edit, selection: Selection.collapsed(rowStart + _emptyCellContentOffset(rowText, column)) };
}

/** Delete the caret's body row. The header row cannot be deleted. */
export const deleteTableRow: EditCommand = ctx => {
	const at = tableCellAt(ctx.document, ctx.selection.active);
	if (!at || at.row === 0) { return undefined; }
	const reference = at.table.rows[at.row];
	const start = lineStart(ctx.text, reference.range.start);
	const breakLength = lineBreakLengthAt(ctx.text, reference.range.endExclusive);
	const range = breakLength > 0
		? new OffsetRange(start, reference.range.endExclusive + breakLength)
		: new OffsetRange(previousLineBreakStart(ctx.text, start) ?? start, reference.range.endExclusive);
	const edit = StringEdit.delete(range);
	const targetRow = at.row < at.table.rows.length - 1 ? at.row : at.row - 1;
	return _withCaretAt(ctx, edit, at.table, targetRow, at.column);
};

/** Insert an empty column left or right of the caret's column, including its delimiter cell. */
export function insertTableColumn(ctx: CursorCommandContext, placement: TableColumnPlacement): EditResult | undefined {
	const at = tableCellAt(ctx.document, ctx.selection.active);
	if (!at) { return undefined; }
	const index = placement === 'left' ? at.column : at.column + 1;
	const replacements: StringReplacement[] = [];
	for (const row of _allRows(at.table)) {
		const isDelimiter = row === at.table.delimiterRow;
		const cell = isDelimiter ? '| --- ' : '|   ';
		if (index < row.cells.length) {
			const start = row.cells[index].range.start;
			replacements.push(StringReplacement.insert(start, ctx.text[start] === '|' ? cell : `${cell}| `));
		} else if (index === row.cells.length) {
			const end = row.range.endExclusive;
			replacements.push(StringReplacement.insert(end, ctx.text[end - 1] === '|'
				? `${cell.slice(1)}|`
				: ` ${cell}|`));
		}
	}
	return _withCaretAt(ctx, new StringEdit(replacements), at.table, at.row, index);
}

/** Delete the caret's column. The last remaining column cannot be deleted. */
export const deleteTableColumn: EditCommand = ctx => {
	const at = tableCellAt(ctx.document, ctx.selection.active);
	if (!at || at.table.columnCount <= 1) { return undefined; }
	const replacements: StringReplacement[] = [];
	for (const row of _allRows(at.table)) {
		const cell = row.cells[at.column];
		if (!cell) { continue; }
		const isLast = at.column === row.cells.length - 1;
		const end = isLast && at.column > 0 && ctx.text[cell.range.endExclusive - 1] === '|'
			? cell.range.endExclusive - 1
			: cell.range.endExclusive;
		replacements.push(StringReplacement.delete(new OffsetRange(cell.range.start, end)));
	}
	return _withCaretAt(ctx, new StringEdit(replacements), at.table, at.row, Math.min(at.column, at.table.columnCount - 2));
};

/** Set the caret column's alignment by rewriting its delimiter cell. */
export function setTableColumnAlignment(ctx: CursorCommandContext, alignment: TableColumnAlignment): EditResult | undefined {
	const at = tableCellAt(ctx.document, ctx.selection.active);
	const delimiter = at?.table.delimiterRow?.cells[at.column];
	if (!at || !delimiter) { return undefined; }
	const source = delimiter.range.substring(ctx.text);
	const match = /:?-+:?/.exec(source);
	if (!match) { return undefined; }
	const dashes = '-'.repeat(Math.max(3, match[0].replace(/:/g, '').length));
	const spec = alignment === 'center' ? `:${dashes}:` : alignment === 'right' ? `${dashes}:` : alignment === 'left' ? `:${dashes}` : dashes;
	if (spec === match[0]) { return undefined; }
	const start = delimiter.range.start + match.index;
	return {
		edit: StringEdit.replace(new OffsetRange(start, start + match[0].length), spec),
		selection: ctx.selection,
	};
}

/** Swap the caret's body row with the body row above or below it. */
export function moveTableRow(ctx: CursorCommandContext, direction: 'up' | 'down'): TableEditOutcome {
	const at = tableCellAt(ctx.document, ctx.selection.active);
	if (!at) { return undefined; }
	const other = direction === 'up' ? at.row - 1 : at.row + 1;
	if (at.row === 0 || other < 1 || other >= at.table.rows.length) { return { result: undefined }; }
	const [first, second] = direction === 'up'
		? [at.table.rows[other], at.table.rows[at.row]]
		: [at.table.rows[at.row], at.table.rows[other]];
	const firstText = first.range.substring(ctx.text);
	const secondText = second.range.substring(ctx.text);
	const edit = new StringEdit([
		StringReplacement.replace(first.range, secondText),
		StringReplacement.replace(second.range, firstText),
	]);
	const delta = direction === 'up'
		? first.range.start - second.range.start
		: secondText.length - firstText.length + (second.range.start - first.range.start);
	const map = (offset: number) => offset + delta;
	return { result: { edit, selection: new Selection(map(ctx.selection.anchor), map(ctx.selection.active)) } };
}

/** Insert a two-column table with a header and one body row, separated from surrounding text by blank lines. */
export const insertTable: EditCommand = ctx => {
	const range = ctx.selection.range;
	if (tableLayoutAt(ctx.document, range.start)) { return undefined; }
	const lb = ctx.lineBreak;
	const lineBegin = lineStart(ctx.text, range.start);
	const previousLineBlank = lineBegin === 0 || /(?:^|\n)\r?\n$/.test(ctx.text.slice(0, lineBegin));
	const before = range.start !== lineBegin ? lb + lb : previousLineBlank ? '' : lb;
	const restOfLine = ctx.text.slice(range.endExclusive, ctx.text.indexOf('\n', range.endExclusive) === -1 ? undefined : ctx.text.indexOf('\n', range.endExclusive)).replace(/\r$/, '');
	const after = restOfLine.length > 0 ? lb + lb : lb;
	const table = ['| Column 1 | Column 2 |', '| -------- | -------- |', '|          |          |'].join(lb);
	const headerStart = range.start + before.length + 2;
	return {
		edit: StringEdit.replace(range, before + table + after),
		selection: new Selection(headerStart, headerStart + 'Column 1'.length),
	};
};

function _allRows(table: TableLayout): readonly TableRowLayout[] {
	return table.delimiterRow ? [table.rows[0], table.delimiterRow, ...table.rows.slice(1)] : table.rows;
}

/**
 * An empty row matching the table's column count. Each cell copies the source
 * width of the reference row's cell, so a padded, aligned table stays aligned.
 */
function _emptyRowText(ctx: CursorCommandContext, table: TableLayout, reference: TableRowLayout): string {
	const cells: string[] = [];
	for (let column = 0; column < table.columnCount; column++) {
		const cell = reference.cells[column] ?? table.rows[0].cells[column];
		let width = cell?.range.length ?? 4;
		if (cell && ctx.text[cell.range.endExclusive - 1] === '|' && cell.range.endExclusive === reference.range.endExclusive) { width--; }
		cells.push('|' + ' '.repeat(Math.max(2, width - 1)));
	}
	return cells.join('') + '|';
}

function _emptyCellContentOffset(rowText: string, column: number): number {
	let pipe = -1;
	for (let i = 0; i <= column; i++) { pipe = rowText.indexOf('|', pipe + 1); }
	return pipe + 2;
}

/**
 * Apply `edit` and place the caret at the start of a cell in the edited table,
 * found by reparsing. Structural commands use this because the target cell's
 * offset depends on the rewritten rows.
 */
function _withCaretAt(ctx: CursorCommandContext, edit: StringEdit, table: TableLayout, row: number, column: number): EditResult | undefined {
	if (edit.isEmpty) { return undefined; }
	const text = edit.apply(ctx.text);
	const updated = tableLayoutAt(parse(text), edit.mapOffset(table.range.start));
	const targetRow = updated?.rows[Math.min(row, updated.rows.length - 1)];
	const cell = targetRow?.cells[Math.min(column, targetRow.cells.length - 1)];
	return { edit, selection: Selection.collapsed(cell ? cell.content.start : edit.mapOffset(ctx.selection.active)) };
}

export type { TableCellPosition };
