import { autorun, derived, observableValue, transaction, type IObservable } from '@vscode/observables';

export class RenameModel<TContext = undefined> {
	readonly name = observableValue(this, '');
	private readonly _session = observableValue<RenameSession<TContext> | undefined>(this, undefined);
	private readonly _pending = observableValue(this, false);
	private readonly _failure = observableValue<{ readonly name: string; readonly error: Error } | undefined>(this, undefined);
	private _submission: AbortController | undefined;
	private _disposed = false;

	readonly session: IObservable<RenameSession<TContext> | undefined> = this._session;
	readonly pending: IObservable<boolean> = this._pending;
	readonly isOpen = derived(this, reader => this._session.read(reader) !== undefined);
	readonly error = derived(this, reader => {
		const failure = this._failure.read(reader);
		return failure?.name === this.name.read(reader) ? failure.error : undefined;
	});
	readonly validationMessage = derived(this, reader => {
		const session = this._session.read(reader);
		const name = this.name.read(reader);
		if (!session) { return undefined; }
		if (!name.trim()) { return 'Enter a new name.'; }
		try {
			return this._options.validate?.(name, session);
		} catch (error) {
			return toError(error).message;
		}
	});
	readonly canSubmit = derived(this, reader =>
		this.isOpen.read(reader) && !this._pending.read(reader)
		&& !this.validationMessage.read(reader)
		&& this.name.read(reader) !== this._session.read(reader)?.initialName);

	private readonly _nameObserver;

	constructor(private readonly _options: RenameModelOptions<TContext>) {
		let previousName = this.name.get();
		this._nameObserver = autorun(reader => {
			const name = this.name.read(reader);
			if (name === previousName) { return; }
			previousName = name;
			this._abortSubmission();
			this._failure.set(undefined, undefined);
		});
	}

	open(session: RenameSession<TContext>): void {
		if (this._disposed) { throw new Error('Cannot open a disposed rename model.'); }
		this._abortSubmission();
		transaction(tx => {
			this._failure.set(undefined, tx);
			this.name.set(session.initialName, tx);
			this._session.set({ ...session }, tx);
		});
	}

	async submit(): Promise<RenameSubmitResult> {
		const session = this._session.get();
		if (!session) { return { kind: 'closed' }; }
		if (this._pending.get()) { return { kind: 'pending' }; }
		const validation = this.validationMessage.get();
		if (validation) { return { kind: 'invalid', message: validation }; }
		const name = this.name.get();
		if (name === session.initialName) {
			this.cancel();
			return { kind: 'cancelled' };
		}

		const submission = new AbortController();
		this._submission = submission;
		transaction(tx => {
			this._failure.set(undefined, tx);
			this._pending.set(true, tx);
		});
		try {
			await this._options.onSubmit({ ...session, name, signal: submission.signal });
		} catch (error) {
			if (!this._isCurrent(session, submission)) { return { kind: 'superseded' }; }
			const failure = toError(error);
			transaction(tx => {
				this._failure.set({ name, error: failure }, tx);
				this._pending.set(false, tx);
			});
			this._submission = undefined;
			return { kind: 'error', error: failure };
		}
		if (!this._isCurrent(session, submission)) { return { kind: 'superseded' }; }
		this._submission = undefined;
		transaction(tx => {
			this._pending.set(false, tx);
			this._session.set(undefined, tx);
		});
		return { kind: 'submitted', name };
	}

	cancel(): void {
		const session = this._session.get();
		this._close();
		if (session) { this._options.onCancel?.(session); }
	}

	dispose(): void {
		if (this._disposed) { return; }
		this._disposed = true;
		this._nameObserver.dispose();
		this._close();
	}

	private _close(): void {
		this._abortSubmission();
		transaction(tx => {
			this._session.set(undefined, tx);
			this._failure.set(undefined, tx);
		});
	}

	private _abortSubmission(): void {
		const submission = this._submission;
		this._submission = undefined;
		this._pending.set(false, undefined);
		submission?.abort();
	}

	private _isCurrent(session: RenameSession<TContext>, submission: AbortController): boolean {
		return this._session.get() === session && this._submission === submission && !submission.signal.aborted;
	}
}

export interface RenameSession<TContext = undefined> {
	readonly initialName: string;
	readonly context: TContext;
}

export interface RenameRequest<TContext = undefined> extends RenameSession<TContext> {
	readonly name: string;
	readonly signal: AbortSignal;
}

export interface RenameModelOptions<TContext = undefined> {
	readonly onSubmit: (request: RenameRequest<TContext>) => void | Promise<void>;
	readonly onCancel?: (session: RenameSession<TContext>) => void;
	readonly validate?: (name: string, session: RenameSession<TContext>) => string | undefined;
}

export type RenameSubmitResult =
	| { readonly kind: 'submitted'; readonly name: string }
	| { readonly kind: 'invalid'; readonly message: string }
	| { readonly kind: 'error'; readonly error: Error }
	| { readonly kind: 'closed' | 'pending' | 'cancelled' | 'superseded' };

function toError(error: unknown): Error {
	if (error instanceof Error && error.message) { return error; }
	return new Error(String(error) || 'Rename failed.');
}
