import type { CodeBlockAstNode } from '../../parser/ast.js';
import { getEmbeddedCodeBlockContent } from './embeddedCodeBlockContent.js';

export function getCodeBlockText(block: CodeBlockAstNode): string {
	const content = block.codeText ?? block.content
		.filter(child => child.kind === 'marker' && child.markerKind === 'content')
		.map(child => child.content).join('');
	return block.openFence
		? getEmbeddedCodeBlockContent(content, block.closeFence !== undefined).text
		: content;
}
