import { OffsetRange } from '../core/offsetRange.js';
import { Selection } from '../core/selection.js';
import { StringEdit } from '../core/stringEdit.js';
import { lineBreakLengthAt, lineEnd, lineStart, nextLineStart, previousLineBreakStart } from '../core/lines.js';
import type { CursorCommandContext, EditCommand } from './types.js';

interface SelectedLines {
	readonly start: number;
	readonly endExclusive: number;
	readonly text: string;
}

interface JoinedLine {
	readonly originalStart: number;
	readonly contentStart: number;
	readonly contentEndExclusive: number;
	readonly outputStart: number;
	readonly outputEndExclusive: number;
}

export const copyLinesUp: EditCommand = ctx => copyLines(ctx, false);
export const copyLinesDown: EditCommand = ctx => copyLines(ctx, true);
export const moveLinesUp: EditCommand = ctx => moveLines(ctx, false);
export const moveLinesDown: EditCommand = ctx => moveLines(ctx, true);

export const deleteLines: EditCommand = ctx => {
	const deletion = linesDeletion(ctx);
	if (!deletion) {
		return undefined;
	}

	const activeColumn = ctx.selection.active - lineStart(ctx.text, ctx.selection.active);
	const edit = StringEdit.delete(deletion.range);
	const result = edit.apply(ctx.text);
	const targetLineEnd = lineEnd(result, deletion.targetLineStart);
	return {
		edit,
		selection: Selection.collapsed(Math.min(deletion.targetLineStart + activeColumn, targetLineEnd)),
	};
};

/**
 * The text an empty-selection copy or cut transfers: the caret's logical
 * source line followed by a line break, even when it is the last line.
 */
export function caretLineClipboardText(ctx: CursorCommandContext): string {
	return `${selectedLines(ctx).text}${ctx.lineBreak}`;
}

/**
 * Delete the caret line like the code editor's empty-selection cut, leaving
 * the caret where the deleted text started.
 */
export const cutCaretLine: EditCommand = ctx => {
	const deletion = linesDeletion(ctx);
	if (!deletion) {
		return undefined;
	}
	return {
		edit: StringEdit.delete(deletion.range),
		selection: Selection.collapsed(deletion.range.start),
	};
};

/**
 * Insert a line copied from an empty selection above the caret line, keeping
 * the caret on its original text, like the code editor's full-line paste.
 */
export function pasteCaretLine(text: string): EditCommand {
	return ctx => {
		if (!ctx.selection.isCollapsed) {
			return undefined;
		}
		return {
			edit: StringEdit.insert(lineStart(ctx.text, ctx.selection.active), text),
			selection: Selection.collapsed(ctx.selection.active + text.length, ctx.selection.activeAffinity),
		};
	};
}

function linesDeletion(ctx: CursorCommandContext): { readonly range: OffsetRange; readonly targetLineStart: number } | undefined {
	if (ctx.text.length === 0) {
		return undefined;
	}

	const lines = selectedLines(ctx);
	if (lines.endExclusive < ctx.text.length) {
		return { range: new OffsetRange(lines.start, lines.endExclusive + lineBreakLengthAt(ctx.text, lines.endExclusive)), targetLineStart: lines.start };
	}
	const previousLineBreak = previousLineBreakStart(ctx.text, lines.start);
	if (previousLineBreak !== undefined) {
		return { range: new OffsetRange(previousLineBreak, lines.endExclusive), targetLineStart: lineStart(ctx.text, previousLineBreak) };
	}
	return { range: new OffsetRange(0, ctx.text.length), targetLineStart: 0 };
}

export const joinLines: EditCommand = ctx => {
	const firstLineStart = lineStart(ctx.text, ctx.selection.range.start);
	const firstLineEnd = lineEnd(ctx.text, firstLineStart);
	if (firstLineEnd === ctx.text.length) {
		return undefined;
	}

	const selected = selectedLines(ctx);
	const lastLineEnd = selected.endExclusive === firstLineEnd
		? lineEnd(ctx.text, nextLineStart(ctx.text, firstLineEnd)!)
		: selected.endExclusive;
	const { text, lines } = joinLineBlock(ctx.text, firstLineStart, lastLineEnd);
	const edit = StringEdit.replace(new OffsetRange(firstLineStart, lastLineEnd), text);
	const selection = ctx.selection.isCollapsed
		? Selection.collapsed(lines[0].outputEndExclusive)
		: new Selection(
			mapJoinedOffset(lines, ctx.selection.anchor),
			mapJoinedOffset(lines, ctx.selection.active),
		);
	return { edit, selection };
};

function copyLines(ctx: CursorCommandContext, down: boolean): ReturnType<EditCommand> {
	const lines = selectedLines(ctx);
	const followingLineStart = nextLineStart(ctx.text, lines.endExclusive);
	if (down && followingLineStart === undefined) {
		return {
			edit: StringEdit.insert(ctx.text.length, ctx.lineBreak + lines.text),
			selection: mapSelectionToBlock(ctx.selection, lines, lines.endExclusive + ctx.lineBreak.length, 0),
		};
	}
	return {
		edit: StringEdit.insert(down ? followingLineStart! : lines.start, lines.text + ctx.lineBreak),
		selection: mapSelectionToBlock(ctx.selection, lines, down ? followingLineStart! : lines.start, ctx.lineBreak.length),
	};
}

function moveLines(ctx: CursorCommandContext, down: boolean): ReturnType<EditCommand> {
	const lines = selectedLines(ctx);
	if (down) {
		const nextStart = nextLineStart(ctx.text, lines.endExclusive);
		if (nextStart === undefined) {
			return undefined;
		}
		const nextEnd = lineEnd(ctx.text, nextStart);
		const nextText = ctx.text.slice(nextStart, nextEnd);
		const separator = ctx.text.slice(lines.endExclusive, nextStart);
		return {
			edit: StringEdit.replace(
				new OffsetRange(lines.start, nextEnd),
				nextText + separator + lines.text,
			),
			selection: mapSelectionToBlock(
				ctx.selection,
				lines,
				lines.start + nextText.length + separator.length,
				lineBreakLengthAt(ctx.text, nextEnd),
			),
		};
	}

	const previousLineBreak = previousLineBreakStart(ctx.text, lines.start);
	if (previousLineBreak === undefined) {
		return undefined;
	}
	const previousStart = lineStart(ctx.text, previousLineBreak);
	const previousText = ctx.text.slice(previousStart, previousLineBreak);
	const separator = ctx.text.slice(previousLineBreak, lines.start);
	return {
		edit: StringEdit.replace(
			new OffsetRange(previousStart, lines.endExclusive),
			lines.text + separator + previousText,
		),
		selection: mapSelectionToBlock(ctx.selection, lines, previousStart, separator.length),
	};
}

function selectedLines(ctx: CursorCommandContext): SelectedLines {
	const range = ctx.selection.range;
	const start = lineStart(ctx.text, range.start);
	const endOffset = !ctx.selection.isCollapsed
		&& range.endExclusive > start
		&& lineStart(ctx.text, range.endExclusive) === range.endExclusive
		? range.endExclusive - 1
		: range.endExclusive;
	const endExclusive = lineEnd(ctx.text, endOffset);
	return {
		start,
		endExclusive,
		text: ctx.text.slice(start, endExclusive),
	};
}

/**
 * Maps `selection` from `lines` to their copy at `targetStart`. An offset after
 * the source lines' line break maps to after the target's line break of
 * `targetLineBreakLength`.
 */
function mapSelectionToBlock(
	selection: Selection,
	lines: SelectedLines,
	targetStart: number,
	targetLineBreakLength: number,
): Selection {
	const mapOffset = (offset: number): number => {
		const relative = offset - lines.start;
		return targetStart + (relative <= lines.text.length ? relative : lines.text.length + targetLineBreakLength);
	};
	return new Selection(mapOffset(selection.anchor), mapOffset(selection.active));
}

function joinLineBlock(
	source: string,
	start: number,
	endExclusive: number,
): { readonly text: string; readonly lines: readonly JoinedLine[] } {
	const originalLines: { readonly start: number; readonly endExclusive: number }[] = [];
	let lineStartOffset = start;
	while (lineStartOffset <= endExclusive) {
		const lineEndOffset = Math.min(lineEnd(source, lineStartOffset), endExclusive);
		originalLines.push({ start: lineStartOffset, endExclusive: lineEndOffset });
		if (lineEndOffset === endExclusive) {
			break;
		}
		lineStartOffset = nextLineStart(source, lineEndOffset)!;
	}

	let joined = '';
	const lines: JoinedLine[] = [];
	for (let i = 0; i < originalLines.length; i++) {
		const line = originalLines[i];
		const isFirst = i === 0;
		const isLast = i === originalLines.length - 1;
		const raw = source.slice(line.start, line.endExclusive);
		const leadingLength = isFirst ? 0 : raw.length - raw.trimStart().length;
		const trailingLength = isLast ? 0 : raw.length - raw.trimEnd().length;
		const contentStart = line.start + leadingLength;
		const contentEndExclusive = Math.max(contentStart, line.endExclusive - trailingLength);
		const content = source.slice(contentStart, contentEndExclusive);
		const separator = joined.length > 0 && content.length > 0 ? ' ' : '';
		joined += separator;
		const outputStart = start + joined.length;
		joined += content;
		lines.push({
			originalStart: line.start,
			contentStart,
			contentEndExclusive,
			outputStart,
			outputEndExclusive: start + joined.length,
		});
	}
	return { text: joined, lines };
}

function mapJoinedOffset(lines: readonly JoinedLine[], offset: number): number {
	let line = lines[0];
	for (let i = lines.length - 1; i >= 0; i--) {
		if (lines[i].originalStart <= offset) {
			line = lines[i];
			break;
		}
	}
	if (offset <= line.contentStart) {
		return line.outputStart;
	}
	if (offset >= line.contentEndExclusive) {
		return line.outputEndExclusive;
	}
	return line.outputStart + offset - line.contentStart;
}
