import type { MarkdownParseOptions } from '../parser/parse.js';

export type EditorPresentation = 'reading' | 'editing';
export type RenderMarkupText = 'none' | 'selection' | 'all';

export interface PresentationPolicy {
	readonly parseOptions: MarkdownParseOptions;
	readonly preserveSourceWhitespace: boolean;
	readonly useSourceLineBreaks: boolean;
}

// Editing favors source-line continuity; permission and markup visibility do not affect parsing.
export const presentationPolicies: Readonly<Record<EditorPresentation, PresentationPolicy>> = {
	reading: {
		parseOptions: {},
		preserveSourceWhitespace: false,
		useSourceLineBreaks: false,
	},
	editing: {
		parseOptions: {
			explicitBlankLineBlocks: true,
			explicitFinalEmptyLine: true,
			preserveTrailingListContinuation: true,
			allowEmptyListItemInterrupts: true,
			requireListMarkerWhitespace: true,
			allowEmptyTaskItems: true,
		},
		preserveSourceWhitespace: true,
		useSourceLineBreaks: true,
	},
};
