export const cursorDocumentStart: CursorCommand = (ctx) => CursorPosition.source(normalizeCursorPosition(
	ctx.document,
	ctx.markerVisibleBlocks,
	ctx.selection.active,
	0,
	'right',
	true,
	ctx.markupSelectionRange ?? ctx.selection.range,
));

export const cursorDocumentEnd: CursorCommand = (ctx) => CursorPosition.source(normalizeCursorPosition(
	ctx.document,
	ctx.markerVisibleBlocks,
	ctx.selection.active,
	ctx.text.length,
	'left',
	true,
	ctx.markupSelectionRange ?? ctx.selection.range,
));

export const cursorVisualLineStart: VisualCursorCommand = (ctx) => {
	if (ctx.cursorPosition.kind === 'virtual') {
		return { position: ctx.cursorPosition, desiredColumn: undefined };
	}
	const lineIndex = ctx.lineMap.lineIndexOfPosition(ctx.cursorPosition);
	if (lineIndex === undefined) {
		return { position: cursorLineStart(ctx), desiredColumn: undefined };
	}
	const visualStart = ctx.lineMap.lineStartOffset(lineIndex);
	const visualEnd = ctx.lineMap.lineEndOffset(lineIndex);
	if (visualStart === undefined || visualEnd === undefined) {
		return { position: cursorLineStart(ctx), desiredColumn: undefined };
	}
	const logicalStart = lineStart(ctx.text, visualStart);
	let firstNonWhitespace = visualStart;
	if (visualStart === logicalStart) {
		while (
			firstNonWhitespace < visualEnd
			&& (ctx.text[firstNonWhitespace] === ' ' || ctx.text[firstNonWhitespace] === '\t')
		) {
			firstNonWhitespace++;
		}
		if (firstNonWhitespace === visualEnd) {
			firstNonWhitespace = visualStart;
		}
	}
	let target = firstNonWhitespace !== visualStart && ctx.selection.active !== firstNonWhitespace
		? firstNonWhitespace
		: visualStart;
	const cell = tableCellAt(ctx.document, ctx.selection.active);
	if (cell) { target = Math.max(visualStart, cell.cell.content.start); }
	return {
		position: CursorPosition.source(normalizeCursorPosition(
			ctx.document,
			ctx.markerVisibleBlocks,
			ctx.selection.active,
			target,
			'right',
			true,
			ctx.markupSelectionRange ?? ctx.selection.range,
		)),
		desiredColumn: undefined,
	};
};

export const cursorVisualLineEnd: VisualCursorCommand = (ctx) => {
	if (ctx.cursorPosition.kind === 'virtual') {
		return { position: ctx.cursorPosition, desiredColumn: undefined };
	}
	const lineIndex = ctx.lineMap.lineIndexOfPosition(ctx.cursorPosition);
	if (lineIndex === undefined) {
		return { position: cursorLineEnd(ctx), desiredColumn: undefined };
	}
	let visualEnd = ctx.lineMap.lineEndOffset(lineIndex);
	if (visualEnd === undefined) {
		return { position: cursorLineEnd(ctx), desiredColumn: undefined };
	}
	const cell = tableCellAt(ctx.document, ctx.selection.active);
	if (cell) { visualEnd = Math.min(visualEnd, cell.cell.content.endExclusive); }
	return {
		position: ctx.lineMap.positionAtOffsetInLine(lineIndex, normalizeCursorPosition(
			ctx.document,
			ctx.markerVisibleBlocks,
			ctx.selection.active,
			visualEnd,
			'left',
			true,
			ctx.markupSelectionRange ?? ctx.selection.range,
		)),
		desiredColumn: undefined,
	};
};

export const cursorDown: VisualCursorCommand = (ctx) => tableColumnMove(ctx, 1, cursorDownByGeometry(ctx));

const cursorDownByGeometry: VisualCursorCommand = (ctx) => {
	const lineIdx = ctx.lineMap.lineIndexOfPosition(ctx.cursorPosition);
	if (lineIdx === undefined) {
		return cursorDownFromUnmeasuredVirtualLine(ctx);
	}
	const x = ctx.desiredColumn ?? ctx.lineMap.xAtPosition(ctx.cursorPosition);
	if (lineIdx >= ctx.lineMap.lineCount - 1) {
		return { position: ctx.cursorPosition, desiredColumn: x };
	}
	return { position: ctx.lineMap.positionInLineAtX(lineIdx + 1, x), desiredColumn: x };
};

export const cursorUp: VisualCursorCommand = (ctx) => tableColumnMove(ctx, -1, cursorUpByGeometry(ctx));

const cursorUpByGeometry: VisualCursorCommand = (ctx) => {
	const lineIdx = ctx.lineMap.lineIndexOfPosition(ctx.cursorPosition);
	if (lineIdx === undefined) {
		return cursorUpFromUnmeasuredVirtualLine(ctx);
	}
	if (ctx.cursorPosition.kind === 'virtual' && lineIdx > 0) {
		return moveToLineEnd(ctx, lineIdx - 1);
	}
	const x = ctx.desiredColumn ?? ctx.lineMap.xAtPosition(ctx.cursorPosition);
	if (lineIdx <= 0) {
		return { position: ctx.cursorPosition, desiredColumn: x };
	}
	return { position: ctx.lineMap.positionInLineAtX(lineIdx - 1, x), desiredColumn: x };
};

function sourceBoundary(
	ctx: Parameters<CursorCommand>[0],
	line: VirtualCursorLine,
	side: 'before' | 'after',
	direction: 'left' | 'right',
): CursorPosition {
	const target = side === 'before' ? line.sourceOffsetBefore : line.sourceOffsetAfter;
	return CursorPosition.source(normalizeCursorPosition(
		ctx.document,
		ctx.markerVisibleBlocks,
		ctx.selection.active,
		target,
		direction,
		true,
		ctx.markupSelectionRange ?? ctx.selection.range,
	));
}

function cursorUpFromUnmeasuredVirtualLine(ctx: Parameters<VisualCursorCommand>[0]) {
	if (ctx.cursorPosition.kind !== 'virtual' || ctx.lineMap.isEmpty) {
		return { position: ctx.cursorPosition, desiredColumn: ctx.desiredColumn };
	}
	const anchorLine = ctx.lineMap.lineIndexOfOffset(ctx.cursorPosition.line.sourceOffsetBefore);
	return moveToLineEnd(ctx, anchorLine);
}

function cursorDownFromUnmeasuredVirtualLine(ctx: Parameters<VisualCursorCommand>[0]) {
	if (ctx.cursorPosition.kind !== 'virtual' || ctx.lineMap.isEmpty) {
		return { position: ctx.cursorPosition, desiredColumn: ctx.desiredColumn };
	}
	const anchorLine = ctx.lineMap.lineIndexOfOffset(ctx.cursorPosition.line.sourceOffsetBefore);
	const x = ctx.desiredColumn ?? ctx.lineMap.lineRect(anchorLine).left;
	if (anchorLine >= ctx.lineMap.lineCount - 1) {
		return { position: ctx.cursorPosition, desiredColumn: x };
	}
	return {
		position: ctx.lineMap.positionInLineAtX(anchorLine + 1, x),
		desiredColumn: x,
	};
}

function moveToLineEnd(ctx: Parameters<VisualCursorCommand>[0], lineIndex: number) {
	const x = ctx.lineMap.lineRect(lineIndex).right;
	return {
		position: ctx.lineMap.positionInLineAtX(lineIndex, x),
		desiredColumn: x,
	};
}

/**
 * Up/Down inside a table stays in the caret's column. Visual lines merge every
 * cell of a row, so when the geometric target leaves the current cell for a
 * different cell, move to the same column of the adjacent row instead: its
 * first visual line going down, its last going up.
 */
function tableColumnMove(ctx: Parameters<VisualCursorCommand>[0], direction: 1 | -1, result: ReturnType<VisualCursorCommand>): ReturnType<VisualCursorCommand> {
	if (ctx.cursorPosition.kind !== 'source' || result.position.kind !== 'source') { return result; }
	const from = tableCellAt(ctx.document, ctx.selection.active);
	if (!from) { return result; }
	const to = tableCellAt(ctx.document, result.position.offset);
	if (to && to.table === from.table && to.cell === from.cell) { return result; }
	const rows = from.table.rows;
	const targetRow = rows[from.row + direction];
	if (!targetRow) {
		if (!from.table.range.contains(result.position.offset)) { return result; }
		const outside = direction > 0 ? from.table.positionAfter : from.table.positionBefore;
		return outside === undefined ? result : { position: CursorPosition.source(outside), desiredColumn: result.desiredColumn };
	}
	const cell = targetRow.cells[Math.min(from.column, targetRow.cells.length - 1)];
	if (!cell) { return result; }
	if (to && to.table === from.table && to.cell === cell) { return result; }
	const x = result.desiredColumn ?? ctx.lineMap.xAtPosition(ctx.cursorPosition);
	const line = ctx.lineMap.lineIndexOfOffset(direction > 0 ? cell.content.start : cell.content.endExclusive);
	const offset = ctx.lineMap.offsetInLineAtX(line, x);
	const clamped = Math.min(Math.max(offset, cell.content.start), cell.content.endExclusive);
	return { position: CursorPosition.source(clamped), desiredColumn: x };
}