import { parse, preprocess, postprocess } from 'micromark';
import { frontmatter } from 'micromark-extension-frontmatter';
import { math } from 'micromark-extension-math';
import { gfmTable } from 'micromark-extension-gfm-table';
import { gfmTaskListItem } from 'micromark-extension-gfm-task-list-item';
import { gfmStrikethrough } from 'micromark-extension-gfm-strikethrough';
import { gfmAutolinkLiteral } from 'micromark-extension-gfm-autolink-literal';
import type { MarkdownParseOptions } from './parse.js';

export interface MicromarkEvent {
	readonly type: 'enter' | 'exit';
	readonly tokenType: string;
	readonly startOffset: number;
	readonly endOffset: number;
	/** Token text without container prefixes that may fall inside its source span. */
	readonly text: string;
}

export function tokenize(source: string, options?: MarkdownParseOptions): MicromarkEvent[] {
	const parser = parse({ extensions: [frontmatter(), math(), gfmTable(), gfmTaskListItem(), gfmStrikethrough(), gfmAutolinkLiteral()] });
	if (options && (options.allowEmptyListItemInterrupts || options.requireListMarkerWhitespace)) {
		configureListPrefixes(parser, source, options);
	}
	if (options?.allowEmptyTaskItems) { configureEmptyTaskItems(parser, source); }
	const chunks = preprocess()(source, undefined, true);
	const nativeEvents = postprocess(parser.document().write(chunks));

	return nativeEvents.map(([type, token, context]) => ({
		type,
		tokenType: token.type,
		startOffset: token.start.offset,
		endOffset: token.end.offset,
		get text() { return context.sliceSerialize(token); },
	}));
}

function configureEmptyTaskItems(parser: ReturnType<typeof parse>, source: string): void {
	const constructs = parser.constructs.text[91];
	const list = Array.isArray(constructs) ? constructs : constructs ? [constructs] : [];
	parser.constructs.text[91] = list.map((construct): typeof construct => construct.name !== 'tasklistCheck' ? construct : {
		...construct,
		tokenize(effects, ok, nok) {
			const prefix = source.slice(this.now().offset);
			const missingValue = /^\[\](?=[ \t\r\n]|$)/.test(prefix);
			const empty = /^\[[ \txX]?\][ \t]*(?:\r\n?|\n|$)/.test(prefix);
			let opened = false;
			let complete = false;
			const start = construct.tokenize.call(this, empty || missingValue ? {
				...effects,
				exit(type) {
					const token = effects.exit(type);
					if (type === 'taskListCheckMarker') { opened = true; }
					if (type === 'taskListCheck') { complete = true; }
					return token;
				},
				// Keep GFM's first-paragraph and checkbox grammar; relax only its nonempty-label lookahead.
				check(checked, onSuccess, onFailure) {
					return effects.check(checked, onSuccess, empty ? onSuccess : onFailure);
				},
			} : effects, ok, code => {
				// A terminal source newline is outside the inline stream, which reports EOF after the checkbox.
				return empty && complete && code === null ? ok(code) : nok(code);
			});
			if (!missingValue) { return start; }
			return code => {
				const inside = start(code);
				if (!opened || !inside) { return inside; }
				// GFM has validated the first-list-paragraph position and consumed the opening bracket.
				return code => {
					if (code !== 93) { return nok(code); }
					effects.enter('taskListCheckMarker');
					effects.consume(code);
					effects.exit('taskListCheckMarker');
					effects.exit('taskListCheck');
					return ok;
				};
			};
		},
	});
}

function configureListPrefixes(parser: ReturnType<typeof parse>, source: string, options: MarkdownParseOptions): void {
	for (const [code, constructs] of Object.entries(parser.constructs.document)) {
		const list = Array.isArray(constructs) ? constructs : constructs ? [constructs] : [];
		parser.constructs.document[code] = list.map((construct): typeof construct => {
			if (construct.name !== 'list') { return construct; }
			const continuation = construct.continuation;
			const configured: typeof construct = {
				...construct,
				...(continuation ? {
					continuation: {
						...continuation,
						tokenize(effects, ok, nok) {
							return continuation.tokenize.call(this, {
								...effects,
								attempt(attempted, onSuccess, onFailure) {
									return effects.attempt(attempted === construct ? configured : attempted, onSuccess, onFailure);
								},
							}, ok, nok);
						},
					},
				} : {}),
				tokenize(effects, ok, nok) {
					const prefix = source.slice(this.now().offset);
					if (options.requireListMarkerWhitespace && /^(?:[*+-]|\d{1,9}[.)])(?:\r\n?|\n|$)/.test(prefix)) {
						return nok;
					}
					// CommonMark rejects blank items when interrupting a paragraph. Reuse its
					// full list grammar, relaxing only that check for an actual empty prefix.
					let context = this;
					if (options.allowEmptyListItemInterrupts && this.interrupt && /^(?:[*+-]|1[.)])[ \t]*(?:\r\n?|\n|$)/.test(prefix)) {
						context = Object.create(this) as typeof this;
						context.interrupt = false;
					}
					return construct.tokenize.call(context, effects, ok, nok);
				},
			};
			return configured;
		});
	}
	if (options.requireListMarkerWhitespace) {
		for (const [code, constructs] of Object.entries(parser.constructs.flow)) {
			const list = Array.isArray(constructs) ? constructs : constructs ? [constructs] : [];
			parser.constructs.flow[code] = list.map((construct): typeof construct => construct.name !== 'setextUnderline' ? construct : {
				...construct,
				tokenize(effects, ok, nok) {
					if (/^-(?:\r\n?|\n|$)/.test(source.slice(this.now().offset))) { return nok; }
					return construct.tokenize.call(this, effects, ok, nok);
				},
			});
		}
	}
}
