import { derived, observableValue, type IObservable } from '@vscode/observables';

export class SuggestModel<T extends SuggestItem = SuggestItem> {
	private readonly _state = observableValue<SuggestState<T>>(this, { kind: 'closed' });
	readonly state: IObservable<SuggestState<T>> = this._state;
	readonly selectedItem = derived(this, reader => {
		const state = this._state.read(reader);
		return state.kind === 'ready' ? state.items[state.selectedIndex] : undefined;
	});

	constructor(private readonly _callbacks: SuggestCallbacks<T>) {}

	show(items: readonly T[], selectedId = this.selectedItem.get()?.id): void {
		const ids = new Set<string>();
		for (const item of items) {
			if (ids.has(item.id)) {
				throw new Error(`Duplicate suggestion id: ${item.id}`);
			}
			ids.add(item.id);
		}
		const selectedIndex = Math.max(0, items.findIndex(item => item.id === selectedId));
		this._update(items.length === 0
			? { kind: 'empty' }
			: { kind: 'ready', items: [...items], selectedIndex });
	}

	showLoading(): void {
		this._update({ kind: 'loading' });
	}

	showError(message: string): void {
		if (!message.trim()) { throw new Error('A suggestion error must have a message.'); }
		this._update({ kind: 'error', message });
	}

	close(): void {
		this._update({ kind: 'closed' });
	}

	select(id: string): boolean {
		const state = this._state.get();
		if (state.kind !== 'ready') { return false; }
		const index = state.items.findIndex(item => item.id === id);
		if (index < 0) { throw new Error(`Unknown suggestion id: ${id}`); }
		this._update({ ...state, selectedIndex: index });
		return true;
	}

	navigate(direction: SuggestNavigation, pageSize = 8): boolean {
		const state = this._state.get();
		if (state.kind !== 'ready') { return false; }
		if (!Number.isInteger(pageSize) || pageSize < 1) {
			throw new Error('Suggestion page size must be a positive integer.');
		}
		const last = state.items.length - 1;
		let index: number;
		switch (direction) {
			case 'next': index = (state.selectedIndex + 1) % state.items.length; break;
			case 'previous': index = (state.selectedIndex + last) % state.items.length; break;
			case 'first': index = 0; break;
			case 'last': index = last; break;
			case 'nextPage': index = Math.min(last, state.selectedIndex + pageSize); break;
			case 'previousPage': index = Math.max(0, state.selectedIndex - pageSize); break;
		}
		this._update({ ...state, selectedIndex: index });
		return true;
	}

	accept(source: SuggestAcceptance = 'enter'): boolean {
		const item = this.selectedItem.get();
		if (!item) { return false; }
		this.close();
		this._callbacks.onAccept(item, source);
		return true;
	}

	cancel(): boolean {
		if (this._state.get().kind === 'closed') { return false; }
		this.close();
		this._callbacks.onCancel?.();
		return true;
	}

	private _update(state: SuggestState<T>): void {
		const previous = this.selectedItem.get();
		this._state.set(state, undefined);
		const selected = this.selectedItem.get();
		if (selected !== previous) { this._callbacks.onSelect?.(selected); }
	}
}

export interface SuggestItem {
	readonly id: string;
	readonly label: string;
	readonly detail?: string;
	readonly type?: string;
	readonly highlightLength?: number;
}

export type SuggestState<T extends SuggestItem = SuggestItem> =
	| { readonly kind: 'closed' }
	| { readonly kind: 'loading' }
	| { readonly kind: 'empty' }
	| { readonly kind: 'error'; readonly message: string }
	| { readonly kind: 'ready'; readonly items: readonly T[]; readonly selectedIndex: number };

export interface SuggestCallbacks<T extends SuggestItem> {
	readonly onAccept: (item: T, source: SuggestAcceptance) => void;
	readonly onCancel?: () => void;
	readonly onSelect?: (item: T | undefined) => void;
}

export type SuggestAcceptance = 'enter' | 'tab' | 'pointer';
export type SuggestNavigation = 'next' | 'previous' | 'first' | 'last' | 'nextPage' | 'previousPage';
