import { OffsetRange } from '../core/offsetRange.js';
import {
	TableAstNode, type AstNode, type DocumentAstNode, type TableCellAstNode, type TableColumnAlignment, type TableRowAstNode,
} from '../parser/ast.js';

/**
 * Absolute source geometry of the GFM tables in a document.
 *
 * A table is edited cell by cell: only {@link TableCellLayout.content} ranges
 * are caret positions and editable text. Pipes, padding, row line breaks, and
 * the delimiter row are structure that commands rewrite deliberately.
 */
export interface TableLayout {
	readonly ast: TableAstNode;
	/** The whole table, including leading trivia and its trailing line break. */
	readonly range: OffsetRange;
	/** The header row followed by the body rows; the delimiter row is excluded. */
	readonly rows: readonly TableRowLayout[];
	readonly delimiterRow: TableRowLayout | undefined;
	readonly columnCount: number;
	readonly alignments: readonly TableColumnAlignment[];
	/** Caret position just before the line break that precedes the table, if any. */
	readonly positionBefore: number | undefined;
	/** Caret position directly after the table, if any. */
	readonly positionAfter: number | undefined;
}

export interface TableRowLayout {
	readonly ast: TableRowAstNode;
	/** The row's source line, without its line break. */
	readonly range: OffsetRange;
	readonly cells: readonly TableCellLayout[];
}

export interface TableCellLayout {
	readonly ast: TableCellAstNode;
	/** The cell's full source, including its leading pipe and padding. */
	readonly range: OffsetRange;
	/** Editable content between the structural pipe and padding. */
	readonly content: OffsetRange;
}

export interface TableCellPosition {
	readonly table: TableLayout;
	/** Index into {@link TableLayout.rows} (0 is the header). */
	readonly row: number;
	readonly column: number;
	readonly cell: TableCellLayout;
}

const layoutCaches = new WeakMap<DocumentAstNode, readonly TableLayout[]>();

/** Every table in the document, including tables nested in quotes and lists, in source order. */
export function tableLayouts(doc: DocumentAstNode): readonly TableLayout[] {
	let layouts = layoutCaches.get(doc);
	if (!layouts) {
		layouts = _collect(doc);
		layoutCaches.set(doc, layouts);
	}
	return layouts;
}

/** The table whose source contains `offset`, treating its end as inside only at the document end. */
export function tableLayoutAt(doc: DocumentAstNode, offset: number): TableLayout | undefined {
	for (const layout of tableLayouts(doc)) {
		if (layout.range.contains(offset) || (offset === doc.length && layout.range.endExclusive === offset)) {
			return layout;
		}
		if (layout.range.start > offset) { break; }
	}
	return undefined;
}

/**
 * The cell whose editable content contains `offset` (both content edges
 * count). Typing trailing spaces moves the caret into the cell's trailing
 * padding, since Markdown strips them from the content, so an offset in that
 * padding also belongs to the cell.
 */
export function tableCellAt(doc: DocumentAstNode, offset: number): TableCellPosition | undefined {
	const table = tableLayoutAt(doc, offset);
	if (!table) { return undefined; }
	let padded: TableCellPosition | undefined;
	for (let row = 0; row < table.rows.length; row++) {
		const cells = table.rows[row].cells;
		for (let column = 0; column < cells.length; column++) {
			const cell = cells[column];
			const content = cell.content;
			if (content.start <= offset && offset <= content.endExclusive) {
				return { table, row, column, cell };
			}
			if (!padded && content.endExclusive < offset && offset <= _paddingEnd(cell, column === cells.length - 1)) {
				padded = { table, row, column, cell };
			}
		}
	}
	return padded;
}

function _paddingEnd(cell: TableCellLayout, isLast: boolean): number {
	const last = cell.ast.content.at(-1);
	const closingPipe = isLast && last !== undefined && 'content' in last && typeof last.content === 'string' && last.content.endsWith('|');
	return cell.range.endExclusive - (closingPipe ? 1 : 0);
}

/**
 * The cell owning `offset` when it lies anywhere in a cell's source, including
 * its pipe and padding. Used to map pointer hits on structure into the cell.
 */
export function tableCellOwning(table: TableLayout, offset: number): TableCellPosition | undefined {
	for (let row = 0; row < table.rows.length; row++) {
		const cells = table.rows[row].cells;
		for (let column = 0; column < cells.length; column++) {
			const range = cells[column].range;
			const isLast = column === cells.length - 1;
			if (range.start <= offset && (offset < range.endExclusive || (isLast && offset === range.endExclusive))) {
				return { table, row, column, cell: cells[column] };
			}
		}
	}
	return undefined;
}

/**
 * Move `target` off table structure. Cell content edges are the only caret
 * positions inside a table, so `right` advances to the next content start (or
 * past the table), `left` retreats to the previous content end (or before the
 * table), and `nearest` clamps into the cell that owns the offset.
 */
export function snapOutOfTableStructure(
	doc: DocumentAstNode,
	target: number,
	direction: 'left' | 'right' | 'nearest',
): number {
	const table = tableLayoutAt(doc, target);
	if (!table) { return target; }
	const cells = table.rows.flatMap(row => row.cells);
	if (cells.some(cell => cell.content.start <= target && target <= cell.content.endExclusive)) { return target; }

	if (direction === 'nearest') {
		const owner = tableCellOwning(table, target);
		if (owner) {
			const content = owner.cell.content;
			return Math.min(Math.max(target, content.start), content.endExclusive);
		}
		const after = cells.find(cell => cell.content.start > target);
		const before = [...cells].reverse().find(cell => cell.content.endExclusive < target);
		if (!before) { return after?.content.start ?? target; }
		if (!after) { return before.content.endExclusive; }
		return target - before.content.endExclusive <= after.content.start - target
			? before.content.endExclusive
			: after.content.start;
	}

	if (direction === 'right') {
		const next = cells.find(cell => cell.content.start > target);
		if (next) { return next.content.start; }
		return table.positionAfter ?? cells.at(-1)?.content.endExclusive ?? target;
	}
	const previous = [...cells].reverse().find(cell => cell.content.endExclusive < target);
	if (previous) { return previous.content.endExclusive; }
	return table.positionBefore ?? cells[0]?.content.start ?? target;
}

function _collect(doc: DocumentAstNode): readonly TableLayout[] {
	const found: { table: TableAstNode; start: number }[] = [];
	const visit = (node: AstNode, start: number): void => {
		if (node instanceof TableAstNode) {
			found.push({ table: node, start });
			return;
		}
		switch (node.kind) {
			case 'document':
			case 'blockQuote':
			case 'list':
			case 'listItem': {
				let offset = start;
				for (const child of node.children) {
					visit(child, offset);
					offset += child.length;
				}
			}
		}
	};
	visit(doc, 0);
	if (found.length === 0) { return []; }
	const text = _sourceText(doc);
	return found.map(({ table, start }) => _layout(table, start, text));
}

function _layout(table: TableAstNode, start: number, text: string): TableLayout {
	const rows: TableRowLayout[] = [];
	let delimiterRow: TableRowLayout | undefined;
	const contentRows = new Set<AstNode>(table.contentRows);
	let offset = start;
	for (const child of table.children) {
		if (child === table.delimiterRow) {
			delimiterRow = _rowLayout(table.delimiterRow, offset);
		} else if (contentRows.has(child)) {
			rows.push(_rowLayout(child as TableRowAstNode, offset));
		}
		offset += child.length;
	}
	const end = start + table.length;
	let before: number | undefined = start - 1;
	if (before < 0) {
		before = undefined;
	} else if (text[before] === '\n' && text[before - 1] === '\r') {
		before--;
	}
	return {
		ast: table,
		range: new OffsetRange(start, end),
		rows,
		delimiterRow,
		columnCount: table.columnCount,
		alignments: table.columnAlignments,
		positionBefore: before,
		positionAfter: end < text.length || /\r?\n$/.test(text.slice(start, end)) ? end : undefined,
	};
}

function _rowLayout(row: TableRowAstNode, start: number): TableRowLayout {
	const cells: TableCellLayout[] = [];
	const cellSet = new Set<AstNode>(row.cells);
	let offset = start;
	for (const child of row.children) {
		if (cellSet.has(child)) {
			const cell = child as TableCellAstNode;
			cells.push({
				ast: cell,
				range: OffsetRange.ofStartAndLength(offset, cell.length),
				content: cell.contentRange.delta(offset),
			});
		}
		offset += child.length;
	}
	return { ast: row, range: OffsetRange.ofStartAndLength(start, row.length), cells };
}

function _sourceText(node: AstNode): string {
	const parts: string[] = [];
	const visit = (n: AstNode): void => {
		const children = n.children;
		if (children.length === 0) {
			const content = (n as { readonly content?: unknown }).content;
			if (typeof content === 'string') { parts.push(content); }
			return;
		}
		for (const child of children) { visit(child); }
	};
	visit(node);
	return parts.join('');
}
